import { TreeAdapter } from '@dreadnought/react/unstyled';
type Node = { id: string; label: string; children?: readonly Node[] };
const records: readonly Node[] = [{ id: 'root', label: 'Документация', children: [{ id: 'leaf', label: 'Начало' }] }];
export function Example() { return <TreeAdapter records={records} getKey={node => node.id} getChildren={node => node.children} getLabel={node => node.label} defaultExpandedKeys={['root']} />; }
